function validate([n, edges]) {
  if (n < 1 || n > 50000) return 'n is between 1 and 5 * 10^4.';
  if (edges.length < 1 || edges.length > n) return 'edges needs 1 to n entries.';
  const degree = new Array(n).fill(0);
  const listed = new Set();
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  let parts = n;
  for (const edge of edges) {
    if (edge.length !== 2) return 'Each edge is [a, b].';
    const [a, b] = edge;
    if (a < 0 || a >= n || b < 0 || b >= n) return 'Edge ends are nodes 0 to n - 1.';
    if (a === b) return 'An edge joins two different nodes.';
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (listed.has(key)) return 'No edge may be listed twice.';
    listed.add(key);
    if (++degree[a] > 2 || ++degree[b] > 2) return 'Each node has at most 2 neighbours.';
    const x = find(a), y = find(b);
    if (x !== y) { root[x] = y; parts--; }
  }
  if (parts !== 1) return 'The graph must be connected.';
  return null;
}

