function maxScore(n, edges) {
  // Connected with every degree at most 2: a path (n - 1 edges) or a cycle (n edges).
  let score = 0;
  let leftEnd = n;
  let rightEnd = n;
  for (let value = n - 1; value >= 1; value--) {
    if (leftEnd >= rightEnd) {
      score += value * leftEnd;
      leftEnd = value;
    } else {
      score += value * rightEnd;
      rightEnd = value;
    }
  }
  if (edges.length === n) {
    score += leftEnd * rightEnd;
  }
  return score;
}

