function maxScore(n, edges) {
  // Try every assignment of the values 1..n to the nodes and score it on the real edges.
  const value = new Array(n).fill(0), used = new Array(n + 1).fill(false);
  let best = 0;
  const assign = node => {
    if (node === n) {
      let score = 0;
      for (const [a, b] of edges) score += value[a] * value[b];
      best = Math.max(best, score);
      return;
    }
    for (let v = 1; v <= n; v++) {
      if (used[v]) continue;
      used[v] = true;
      value[node] = v;
      assign(node + 1);
      used[v] = false;
    }
  };
  assign(0);
  return best;
}

