function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1500 + pick(501) : 2 + pick(7);
  const cycle = n >= 3 && rand() < 0.5;
  // Lay the nodes along a path in shuffled order, and close it into a cycle half of the time.
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [order[i], order[j]] = [order[j], order[i]]; }
  const edges = [];
  for (let i = 0; i + 1 < n; i++) edges.push([order[i], order[i + 1]]);
  if (cycle) edges.push([order[n - 1], order[0]]);
  // Random edge directions and order, so the list never reads as the path itself.
  for (const edge of edges) if (rand() < 0.5) edge.reverse();
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(i + 1); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  return [n, edges];
}
